"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

import datetime
import re
from dataclasses import dataclass

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"

_MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")
_NUMERIC_DIRECTIVES = frozenset({"max-age", "s-maxage", "min-fresh", "max-stale"})
_REVALIDATE_RESPONSE_DIRECTIVES = ("no-store", "no-cache", "must-revalidate")
_EPOCH = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
_IMF_FIXDATE = re.compile(
    r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), "
    r"([0-9]{2}) (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)
_DIGITS = re.compile(r"[0-9]+")


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


def _split_directives(value: str) -> list[str]:
    elements = []
    current = []
    in_quotes = False
    for char in value:
        if char == '"':
            in_quotes = not in_quotes
        if char == "," and not in_quotes:
            elements.append("".join(current))
            current = []
        else:
            current.append(char)
    elements.append("".join(current))
    return elements


def _parse_cache_control(value: str) -> dict[str, int | None]:
    directives: dict[str, int | None] = {}
    for element in _split_directives(value):
        element = element.strip()
        if not element:
            continue
        name, separator, raw = element.partition("=")
        name = name.strip().lower()
        if not separator:
            if name not in _NUMERIC_DIRECTIVES or name == "max-stale":
                directives[name] = None
            continue
        if name not in _NUMERIC_DIRECTIVES:
            directives[name] = None
            continue
        raw = raw.strip()
        if len(raw) >= 2 and raw[0] == raw[-1] == '"':
            raw = raw[1:-1]
        # A malformed value is treated as absent, so it must not shadow an earlier valid one.
        if _DIGITS.fullmatch(raw):
            directives[name] = int(raw)
    return directives


def _parse_http_date(value: str) -> int:
    match = _IMF_FIXDATE.fullmatch(value.strip())
    if match is None:
        raise HeaderError(f"not an IMF-fixdate: {value!r}")
    day, month, year, hour, minute, second = match.groups()
    try:
        moment = datetime.datetime(
            int(year),
            _MONTHS.index(month) + 1,
            int(day),
            int(hour),
            int(minute),
            int(second),
            tzinfo=datetime.timezone.utc,
        )
    except ValueError as exc:
        raise HeaderError(f"not a real date and time: {value!r}") from exc
    return (moment - _EPOCH) // datetime.timedelta(seconds=1)


def _parse_age(value: str | None) -> int:
    if value is None:
        return 0
    stripped = value.strip()
    if _DIGITS.fullmatch(stripped):
        return int(stripped)
    return 0


def _freshness_lifetime(
    response_cc: dict[str, int | None],
    expires: int | None,
    last_modified: int | None,
    date: int,
) -> int:
    if "s-maxage" in response_cc:
        return response_cc["s-maxage"]
    if "max-age" in response_cc:
        return response_cc["max-age"]
    if expires is not None:
        return max(0, expires - date)
    if last_modified is not None:
        return max(0, (date - last_modified) // 10)
    return 0


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""
    resp = {name.lower(): value for name, value in response_headers.items()}
    req = {name.lower(): value for name, value in request_headers.items()}

    date = _parse_http_date(resp["date"]) if "date" in resp else response_time
    expires = _parse_http_date(resp["expires"]) if "expires" in resp else None
    last_modified = _parse_http_date(resp["last-modified"]) if "last-modified" in resp else None

    response_cc = _parse_cache_control(resp.get("cache-control", ""))
    request_cc = _parse_cache_control(req.get("cache-control", ""))

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date)
    corrected_age = _parse_age(resp.get("age")) + response_delay
    initial_age = max(apparent_age, corrected_age)
    current_age = initial_age + (now - response_time)

    lifetime = _freshness_lifetime(response_cc, expires, last_modified, date)
    if "max-age" in request_cc:
        lifetime = min(lifetime, request_cc["max-age"])

    if any(name in response_cc for name in _REVALIDATE_RESPONSE_DIRECTIVES) or "no-cache" in request_cc:
        verdict = MUST_REVALIDATE
    elif lifetime > current_age + request_cc.get("min-fresh", 0):
        verdict = FRESH
    elif "max-stale" in request_cc and (
        request_cc["max-stale"] is None or current_age - lifetime <= request_cc["max-stale"]
    ):
        verdict = FRESH
    else:
        verdict = STALE

    return Result(verdict=verdict, current_age=current_age, freshness_lifetime=lifetime)
